(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const btn = [...document.querySelectorAll('button')].find((b) => (b.textContent || '').includes('课程演示'));
  if (!btn) return JSON.stringify({ demoButton: false, buttons: [...document.querySelectorAll('button')].map((b) => (b.textContent || '').trim().slice(0, 12)) });
  btn.click();
  await sleep(6000);
  return JSON.stringify({ demoButton: true, path: location.pathname, hasToken: !!localStorage.getItem('token') });
})()
